import os
from typing import Optional, Union

from .qc.reader import Reader
from .report.collector import ResultCollector, collect
from .report.creator import ReportCreator
from .report.matcher import QCMatcher
from .report.status import StatusPrinter
from .rp.client import ReportingPortalClient
from .testline import TestLine
from .utils.directories import Directories
from .utils.logger import logger
from .utils.variables import get_json_env_variable_value


from .environment import SendBackupEnvironment, SendFileEnvironment


class BaseAction:
    def __init__(self, base_name: str, base_dir: Optional[str] = "."):
        """
        :param string base_name: Name needed to create required directories.
        :param string base_dir:  Directory where everything will be saved.
        """
        self._log_level = "INFO"
        self._status = StatusPrinter()
        self.dirs = Directories(base_name=base_name, base_dir=base_dir)

    def clean(self):
        """Remove created dir."""
        self.dirs.remove_dir()

    def _configure_log_level(self, debug):
        if debug:
            logger.set_logger_level("DEBUG")
        else:
            logger.set_logger_level(self._log_level)


class ReportAction(BaseAction):
    FISHEYE_URL = "https://fisheye3.inside.nsn.com/browse/robotlte/trunk/testsuite/"

    def __init__(
        self,
        env: Union[SendBackupEnvironment, SendFileEnvironment],
        backup_dir: Optional[str] = "/tmp/bts_report_backup",
    ):
        """
        :param instance of [SendBackupEnvironment || SendFileEnvironment] env:
                    A class that represents environment state and provides necessary report information
        :param string backup_dir: Path to directory where backup files will be stored.
        """
        super().__init__(base_name="reporting_portal_report")
        self.env = env
        self.dirs.backup_dir = backup_dir
        self._report_creator = None
        self._collector = None
        self._collected = None
        self._zipfile_path = None

    def create_report_and_send(self):
        """Run necessary steps to report test execution result to Reporting Portal."""
        self.create_report("send")
        self._send()

    def create_report(self, command: Optional[str] = "backup"):
        """Run necessary steps to report test execution result to Reporting Portal."""
        self._configure_log_level(self.env.logging_level)

        self._status.print_start_info(self.env)
        self.dirs.create_dir()
        self.dirs.create_sub_dir("collected")

        test_line = TestLine(self.env, self.dirs)

        test_line.configure_test_line()

        if command == "send":
            self.dirs.clean_sub_dir()

        try:
            self.collect_summary(test_line)
        except Exception as e:
            logger.error("""
            Error creating report. Please check if a connection to the Reporting Portal
            exists and if the output.xml file is available.
            """)
            logger.type_of_error_info(e)

    def collect_summary(self, test_line):
        collector = ResultCollector(environment=self.env, test_line=test_line)
        self._collected = collect(collector, self.env)
        cm_test_information_data = get_json_env_variable_value(
            "CM_TEST_INFORMATION", {}
        )
        if not self._is_qc_info_available(cm_test_information_data):
            QCMatcher(self._collected, self.env).match_configs()
        self._collected.update_summary()
        if self._collected.suite_empty is not None:
            self._report_creator = ReportCreator()
            self._report_creator.create_json_report_file(
                self.dirs.subdir_path, self._collected
            )
            self._zipfile_path = self._report_creator.zip_directory(
                self.dirs.subdir_path, self.dirs.dir_path
            )
            self._status.print_suite_summary_info(self._collected.summary)
            if self._zipfile_path:
                self._status.print_backup_end_info()

    @staticmethod
    def _is_qc_info_available(cm_test_information_data: dict) -> bool:
        required_qc_parameters = {"qc_domain", "qc_project", "id"}
        result = True
        try:
            test = cm_test_information_data["tests"][0]
            parameters = {p["name"] for p in test["parameters"]}
            if not required_qc_parameters.issubset(parameters):
                result = False
        except (KeyError, IndexError):
            result = False

        return result

    def _send(self) -> None:
        rp = ReportingPortalClient(rp_url=self.env.custom_rp_url)
        if self._zipfile_path:
            response = rp.send_zip_report(self._zipfile_path)
            response.save_link(
                os.path.join(self.dirs.dir_path, "reporting_portal_link.txt")
            )
            response.save_hash(
                os.path.join(self.dirs.dir_path, "reporting_portal_hash.txt")
            )
            self._status.print_end_info()
        else:
            self._status.print_empty_suite_end_info()

    def send_file(self) -> None:
        """
        Run necessary steps to send zipped test execution report to Reporting Portal.
        """
        self._configure_log_level(self.env.logging_level)

        rp = ReportingPortalClient(rp_url=self.env.custom_rp_url)
        self._status.print_send_file_start_info(self.env)
        response = rp.send_zip_report(self.env.zipfile_path)
        zipfile_dir = self.env.zipfile_path.rsplit("/")[0]
        response.save_link(os.path.join(zipfile_dir, "reporting_portal_link.txt"))
        response.save_hash(os.path.join(zipfile_dir, "reporting_portal_hash.txt"))
        self._status.print_end_info()


class ValidateAction(BaseAction):

    def __init__(self, env):
        super().__init__(base_name="verify_config")
        self.env = env

    def run(self) -> None:
        """Run necessary steps to validate QC configuration."""
        self._status.print_validate_start_info()
        self._configure_log_level(self.env.logging_level)

        reader = Reader(
            self.env.suite_path,
            self.env.sw_version,
            self.env.qc_config_path,
            self.env.label,
        )
        configs = reader.read_test_cases_configs()
        if configs:
            response = ReportingPortalClient(
                rp_url=self.env.custom_rp_url
            ).validate_configs(configs, self.env.sw_version)
            ReportCreator().save_validation_result_to_file(configs, response)
            self._status.print_validation_result(response)
        else:
            self._status.print_validate_empty_configs_info()

        self._status.print_validate_end_info()
